import{_ as i,C as s,o as t,c as n,a2 as a,b as d,w as r,a as c,E as l,a3 as h}from"./chunks/framework.Bqn-bhhR.js";const T=JSON.parse('{"title":"Tree-sitter & Syntax Trees","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tree-sitter.md","filePath":"guide/tree-sitter.md","lastUpdated":1786047222000}'),m={name:"guide/tree-sitter.md"};function u(g,e,p,f,_,y){const o=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="tree-sitter-syntax-trees" tabindex="-1">Tree-sitter &amp; Syntax Trees <a class="header-anchor" href="#tree-sitter-syntax-trees" aria-label="Permalink to &quot;Tree-sitter &amp; Syntax Trees&quot;">​</a></h1><p>Codemark doesn&#39;t store line numbers. It stores a <strong>tree-sitter query</strong> that identifies code by its position in the Abstract Syntax Tree (AST). This page covers how source is parsed into a tree; the next page covers how a bookmark target becomes a query.</p><h2 id="why-tree-sitter" tabindex="-1">Why tree-sitter? <a class="header-anchor" href="#why-tree-sitter" aria-label="Permalink to &quot;Why tree-sitter?&quot;">​</a></h2><p>A <code>file:42</code> reference is brittle — insert a single line above it and it now points at the wrong code. Tree-sitter parses source into a concrete syntax tree where every node has a <em>type</em> (<code>function_item</code>, <code>class_declaration</code>, <code>if_statement</code>) and most have a <em>name</em> (<code>validate_token</code>, <code>AuthService</code>). Anchoring a bookmark to &quot;the function named <code>validate_token</code>&quot; survives anything that doesn&#39;t rename the function, because the <em>identity</em> of the node is what&#39;s recorded, not its coordinates.</p><p>Tree-sitter is also fast and incremental, so re-parsing a file to resolve a bookmark takes milliseconds.</p><h2 id="two-tier-language-model" tabindex="-1">Two-tier language model <a class="header-anchor" href="#two-tier-language-model" aria-label="Permalink to &quot;Two-tier language model&quot;">​</a></h2><p>Codemark knows languages two ways:</p><ul><li><strong>Built-in languages</strong> are statically compiled into the binary: <code>tree_sitter_rust</code>, <code>tree_sitter_swift</code>, <code>tree_sitter_typescript</code>, … These are always available and always win — a built-in name or extension can never be shadowed by a dynamic grammar.</li><li><strong>Dynamic (WASM) grammars</strong> are loaded at runtime from a cache directory. You drop a <code>grammar.wasm</code> + <code>manifest.json</code> into the grammar cache and Codemark understands a new language with no recompilation. See <a href="./dynamic-grammars">Dynamic Grammars</a>.</li></ul>',8)),(t(),d(h,null,{default:r(()=>[l(o,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20LR%0A%20%20SRC%5B%22source%20file%22%5D%20--%3E%20P%5Btree-sitter%20Parser%5D%0A%20%20P%20--%3E%20T%5B%22Syntax%20Tree%5Cn(AST)%22%5D%0A%20%20T%20--%3E%20N%5B%22named%20nodes%3A%5Cnfunction_item%2C%20class_declaration%2C%20...%22%5D%0A%20%20N%20--%3E%20Q%5B%22bookmark%20%3D%20a%20query%5Cnthat%20selects%20one%20node%22%5D%0A%20%20Q%20-.%20re-resolve%20later%20.-%3E%20T2%5B%22new%20tree%20after%20edits%22%5D%0A%20%20T2%20--%3E%20M%5B%22match%20%40target%5Cn%E2%86%92%20active%20%2F%20drifted%20%2F%20stale%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="the-per-language-profile" tabindex="-1">The per-language Profile <a class="header-anchor" href="#the-per-language-profile" aria-label="Permalink to &quot;The per-language Profile&quot;">​</a></h2><p>Every language carries a <strong><code>Profile</code></strong> — structural metadata that drives query generation, classification, and breadcrumbs. It has three parts:</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td><code>landmark_kinds</code></td><td>Which node types are valid query anchors (e.g. <code>function_item</code>, <code>struct_item</code>, <code>impl_item</code>). This is the load-bearing field for query stability.</td></tr><tr><td><code>node_labels</code></td><td>Maps raw node types to human labels (<code>function_item</code> → &quot;function&quot;), driving icons and summaries.</td></tr><tr><td><code>containers</code></td><td><code>(node_kind, name_field)</code> pairs for UI breadcrumb extraction (e.g. <code>(&quot;impl_item&quot;, &quot;type&quot;)</code>).</td></tr></tbody></table><p>Built-in languages have compile-time profiles; dynamic grammars load their profile from <code>manifest.json</code> (every field is <code>#[serde(default)]</code>, so partial profiles work). If a profile omits a kind, a cross-language <code>DECLARATION_TYPES</code> fallback union covers it.</p><h2 id="what-gets-parsed-and-when" tabindex="-1">What gets parsed and when <a class="header-anchor" href="#what-gets-parsed-and-when" aria-label="Permalink to &quot;What gets parsed and when&quot;">​</a></h2><ul><li><strong>At bookmark creation</strong>, the file is parsed and the generator builds a query (see <a href="./query-generation">Query Generation</a>).</li><li><strong>At resolution</strong>, the file is re-parsed fresh and the stored query is run against the current tree (see <a href="./health-status">Health Status</a>).</li><li><strong>In the TUI</strong>, a background parse cache (<code>HashMap&lt;Language, ParseCache&gt;</code>) feeds code previews with debouncing so stepping through a collection stays responsive.</li></ul><p>Because the query is the durable identity and the tree is rebuilt each time, edits that move code around don&#39;t invalidate the bookmark — they just change which node the query matches.</p>',7))])}const w=i(m,[["render",u]]);export{T as __pageData,w as default};
